const isWindowAvailable: boolean = typeof window !== "undefined";

const userAgent: string = isWindowAvailable && typeof navigator !== "undefined"
	? navigator.userAgent
	: "";

interface EnvFlags  {
	isIE: boolean;
	isOpera: boolean;
	isChrome: boolean;
	isKHTML: boolean;
	isFF: boolean;
	isIPad: boolean;
	isEdge: boolean;
	isNode: boolean;
}

const env: EnvFlags  = {
	isIE: userAgent.includes("MSIE") || userAgent.includes("Trident"),
	isOpera: userAgent.includes("Opera"),
	isChrome: userAgent.includes("Chrome"),
	isKHTML: userAgent.includes("Safari") || userAgent.includes("Konqueror"),
	isFF: userAgent.includes("Firefox"),
	isIPad: /iPad/i.test(userAgent),
	isEdge: userAgent.includes("Edge"),
	isNode: !isWindowAvailable || typeof navigator === "undefined",
};

export default env;